//! The shim's logic, in a library so it can be tested.
//!
//! Lumina copies the shim executable into `<data-root>/bin/.shims/` once per
//! command (`php.exe`, `composer.exe`, `node.exe`, ...). Next to each copy is
//! a `<name>.shim` text file that Lumina rewrites whenever the active version
//! changes:
//!
//! ```text
//! # Generated by Lumina: PHP 8.4.26
//! C:\Lumina\bin\php\8.4.26\php.exe
//! -c
//! C:\Lumina\etc\php\8.4.26\php.ini
//! ```
//!
//! The first line that is not a comment is the program; every further line is
//! one argument placed before the user's own. So PATH points at one folder
//! forever, and `php -v` follows the version chosen in Lumina.

use std::path::{Path, PathBuf};

/// What a shim runs.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Target {
    pub program: PathBuf,
    pub args: Vec<String>,
}

/// Parses a `.shim` file.
pub fn parse(text: &str) -> Option<Target> {
    let mut lines = text
        .lines()
        .map(|l| l.trim_end_matches('\r'))
        .filter(|l| !l.starts_with('#') && !l.trim().is_empty());
    let program = PathBuf::from(lines.next()?.trim());
    Some(Target {
        program,
        args: lines.map(str::to_owned).collect(),
    })
}

/// Renders a `.shim` file.
pub fn render(comment: &str, target: &Target) -> String {
    let mut out = format!("# {comment}\n{}\n", target.program.display());
    for arg in &target.args {
        out.push_str(arg);
        out.push('\n');
    }
    out
}

/// `<shim exe without extension>.shim`.
pub fn shim_file(exe: &Path) -> PathBuf {
    exe.with_extension("shim")
}

/// The command name the shim was started as (`php` for `php.exe`).
pub fn command_name(exe: &Path) -> String {
    exe.file_stem()
        .map(|s| s.to_string_lossy().into_owned())
        .unwrap_or_else(|| "shim".into())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn round_trip() {
        let target = Target {
            program: PathBuf::from(r"C:\Lumina\bin\php\8.4.26\php.exe"),
            args: vec!["-c".into(), r"C:\Lumina\etc\php\8.4.26\php.ini".into()],
        };
        let text = render("Generated by Lumina: PHP 8.4.26", &target);
        assert!(text.starts_with("# Generated by Lumina"));
        assert_eq!(parse(&text), Some(target.clone()));
        assert_eq!(parse(&text.replace('\n', "\r\n")), Some(target));
        assert_eq!(parse("# only a comment\n\n"), None);
    }

    #[test]
    fn names() {
        assert_eq!(command_name(Path::new(r"C:\x\.shims\php.exe")), "php");
        assert_eq!(
            shim_file(Path::new("/x/.shims/node")),
            PathBuf::from("/x/.shims/node.shim")
        );
    }
}
